mutation AddCemetery($cemetery: CemeteryInput, $exp: String, $duplicateToken: ID) {
    createCemetery(cemetery: $cemetery, explanation: $exp, duplicateToken: $duplicateToken) {
        id
        fullId
        type
        names {
            name
            language
            abbreviation
        }
    }
}

mutation ApproveEdits($ids: [ID!]!) {
    approveEdits(ids: $ids) {
        result
    }
}

mutation CancelEdits($ids: [ID!]!) {
    cancelEdits(ids: $ids) {
        result
    }
}

query CemeteryDuplicates($cemetery: CemeteryInput, $max: Int) {
    getPossibleCemeteryDuplicates(cemetery: $cemetery, max: $max) {
        duplicates {
            id,
            fullId,
            names {
                name,
                abbreviation,
                language
            },
            coordinates {
                lat,
                lon
            },
            locations {
                continent,
                country,
                state,
                county,
                city
            }
        },
        count,
        duplicateToken
    }
}

query CemeteryNameTypeahead($search: CemeterySearchInput) {
    cemeteries(search: $search) {
        total
        cemeteries {
            id
            fullId
            names {
                language
                name
            }
        }
    }
}

query ContributorFriends($ids: [ID!]!, $from: Int, $size: Int, $contributorId: ID) {
    contributorsById(ids: $ids) {
        id
        publicName
        following(from: $from, size: $size, contributorId: $contributorId) {
            total
            contributors {
                id
                publicName
                photo {
                    id
                    path
                }
            }
        }
    }
}

mutation DeclineEdits($params: DeclineEditInput!) {
    declineEdits(params: $params) {
        result
    }
}

query FindCemetery($id: ID!) {
    cemeteries(ids:[$id]) {
