                __typename
                ... on StringEdit {
                    stringValue
                }
                ... on IntEdit {
                    intValue
                }
                ... on BooleanEdit {
                    booleanValue
                }
                ... on DateEdit {
                    day
                    month
                    year
                }
                ... on TagEdit {
                    tagId
                    name
                }
                ... on GpsEdit {
                    lat
                    lon
                }
                ... on BurialEdit {
                    cemetery {
                        id
                        fullId
                    }
                    disposition
                }
                ... on LocationEdit {
                    location {
                        id
                    }
                }
                ... on RelationshipEdit {
                    memorial {
                        id
                        name {
                            first
                            last
                            maiden
                            nickname
                            given
                            middle
                            primary
                        }
                    }
                    target {
                        id
                        name {
                            first
                            last
                            maiden
                            nickname
                            given
                            middle
                            primary
